@group(0) @binding(6) var<storage, read_write> bout: array<f32>;

@compute @workgroup_size(64)
fn main(@builtin(local_invocation_index) lid: u32, @builtin(workgroup_id) wid: vec3<u32>, @builtin(num_workgroups) nwg: vec3<u32>) {
    let tid: i32 = i32(lid);
    let bid: i32 = i32(wid.x) + i32(wid.y) * i32(nwg.x);
    if (bid >= 50176i) { return; }
    var v_in1: f32 = 0.0;
    var v_in2: f32 = 0.0;
    var v_v2: f32 = 0.0;
    var v_in3: f32 = 0.0;
    var v_v4: f32 = 0.0;
    var v_v5: f32 = 0.0;
    var v_v6: f32 = 0.0;
    var v_in4: f32 = 0.0;
    var v_v8: f32 = 0.0;
    var v_in5: f32 = 0.0;
    var v_v9: f32 = 0.0;
    var v_in0: f32 = 0.0;
    var v_v0: f32 = 0.0;
    var v_v1: f32 = 0.0;
    var v_v3: f32 = 0.0;
    var v_v7: f32 = 0.0;
    var v_v10: f32 = 0.0;
    var v_v11: f32 = 0.0;
    var v_v12: f32 = 0.0;
    var v_v13: f32 = 0.0;
    var v_v14: f32 = 0.0;
    var v_v15: f32 = 0.0;
    var n_e: i32 = 0i;
    n_e = ((64i * bid) + tid);
    if (n_e < 3211264i) {
        v_in1 = b5[(((n_e / 3136i) % 256i) + (256i * (n_e / 802816i)))];
        v_in2 = b3[(((n_e / 3136i) % 256i) % 256i)];
        v_v2 = v_in2;
        v_in3 = b2[(((n_e / 3136i) % 256i) % 256i)];
        v_v4 = v_in3;
        v_v5 = (0.00001 + v_v4);
        v_v6 = sqrt(v_v5);
        v_in4 = b1[(((n_e / 3136i) % 256i) % 256i)];
        v_v8 = v_in4;
        v_in5 = b0[(((n_e / 3136i) % 256i) % 256i)];
        v_v9 = v_in5;
        v_in0 = b4[((((3136i * ((n_e / 3136i) % 256i)) + (56i * ((n_e / 56i) % 56i))) + (n_e % 56i)) + (802816i * (n_e / 802816i)))];
        v_v0 = (v_in0 * v_in1);
        v_v1 = v_v0;
        v_v3 = (v_v1 - v_v2);
        v_v7 = (v_v3 / v_v6);
        v_v10 = fma(v_v7, v_v8, v_v9);
        v_v11 = v_v10;
        v_v12 = v_v11;
        v_v13 = (1.0 / (1.0 + exp(-(v_v12))));
        v_v14 = (v_v12 * v_v13);
        v_v15 = v_v14;
        bout[((((3136i * ((n_e / 3136i) % 256i)) + (56i * ((n_e / 56i) % 56i))) + (n_e % 56i)) + (802816i * (n_e / 802816i)))] = v_v15;
    }
}
